edits.new:
mainWindow.webContents.setWindowOpenHandler(({ url }) => {
  try {
    const parsed = new URL(url);

    if (
      parsed.hostname === "pi.ai" ||
      parsed.hostname.endsWith(".pi.ai")
    ) {
      mainWindow.loadURL(url);
      return { action: "deny" };
    }

    shell.openExternal(url);
    return { action: "deny" };
  } catch {
    return { action: "deny" };
  }
});

mainWindow.loadURL("https://pi.ai/");

edits.old:
mainWindow.webContents.setWindowOpenHandler(({ url }) => {
  try {
    const parsed = new URL(url);

    if (
      parsed.hostname === "hey.pi.ai" ||
      parsed.hostname === "pi.ai" ||
      parsed.hostname.endsWith(".pi.ai")
    ) {
      return {
        action: "allow",
        overrideBrowserWindowOptions: {
          width: 520,
          height: 720,
          autoHideMenuBar: true,
          webPreferences: {
            nodeIntegration: false,
            contextIsolation: true,
            sandbox: true
          }
        }
      };
    }

    shell.openExternal(url);
    return { action: "deny" };
  } catch {
    return { action: "deny" };
  }
});

mainWindow.loadURL("https://hey.pi.ai/");
